<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\SmtpOutboundConfigSenderEmailVO;

trait SmtpOutboundConfigSenderEmailAttributeHolder
{
    protected SmtpOutboundConfigSenderEmailVO|string|null $senderEmail = null;
    protected bool $senderEmailAssigned = false;

    public function getSenderEmailOrCurrent(SmtpOutboundConfigSenderEmailVO $senderEmail): SmtpOutboundConfigSenderEmailVO
    {
        if ($this->senderEmailAssigned) {
            \assert(null !== $this->senderEmail);
            return SmtpOutboundConfigSenderEmailVO::from($this->senderEmail);
        } else {
            return $senderEmail;
        }
    }
    public function senderEmailTryBuildInitial(ConstraintFailList $error): ?SmtpOutboundConfigSenderEmailVO
    {
        return  SmtpOutboundConfigSenderEmailVO::tryFrom($this->senderEmailAssigned ? $this->senderEmail : null, $error);
    }
    public function senderEmail(SmtpOutboundConfigSenderEmailVO|string $senderEmail): static
    {
        $this->senderEmail = $senderEmail;
        $this->senderEmailAssigned = true;
        return $this;
    }
    public function getSenderEmail(): ?string
    {
        return $this->senderEmail instanceof SmtpOutboundConfigSenderEmailVO ? $this->senderEmail->value() : $this->senderEmail;
    }
    public function isSenderEmailAssigned(): bool
    {
        return $this->senderEmailAssigned;
    }
    public function writeSenderEmailTo(mixed $att): void
    {
        if ($this->senderEmailAssigned) {
            \assert(null !== $this->senderEmail);
            $att->senderEmail($this->senderEmail);
        }
    }
    public function readSenderEmailFrom(mixed $att): void
    {
        if ($att->isSenderEmailAssigned()) {
            $senderEmail = $att->getSenderEmail();
            \assert(null !== $senderEmail);
            $this->senderEmail($senderEmail);
        }
    }
    public function unsetSenderEmail(): static
    {
        $this->senderEmailAssigned = false;
        return $this;
    }
    protected function withDefaultSenderEmail(): void
    {
    }
    protected function withAssertedSenderEmailRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->senderEmailAssigned = $this->senderEmailAssigned) {
            $value->senderEmail = SmtpOutboundConfigSenderEmailVO::tryFrom($this->senderEmail, $errorsList);
        }
    }
}
